changeSet.sql:
-- Remaining legacy v11-log-* afterEvents patterns → v3-hive-log-* UPDATE hive_correlation_rules SET rule_after_events_def = regexp_replace( rule_after_events_def, '"indexPattern":"v11-log-[^"]*"', '"indexPattern":"v3-hive-log-*"', 'g' ) WHERE rule_after_events_def ~ '"indexPattern":"v11-log-';
-- Leftover underscore form from 20260713003 → v3-hive-log-* UPDATE hive_correlation_rules SET rule_after_events_def = regexp_replace( rule_after_events_def, '"indexPattern":"_v3_hive_log[^"]*"', '"indexPattern":"v3-hive-log-*"', 'g' ) WHERE rule_after_events_def ~ '"indexPattern":"_v3_hive_log';
-- Normalize source-specific v3-hive-log-<source>-* (not already v3-hive-log-*) UPDATE hive_correlation_rules SET rule_after_events_def = regexp_replace( rule_after_events_def, '"indexPattern":"v3-hive-log-[^*"][^"]*"', '"indexPattern":"v3-hive-log-*"', 'g' ) WHERE rule_after_events_def ~ '"indexPattern":"v3-hive-log-[^*"]';
